import sys, os, json, re
sys.path.append('storage/shared')

try:
    from meta.sas.aggregator import load_beacons, advise_all
    from meta.sas.nominals import compute_centers
    from meta.sas.entropy import compute_per_agent_entropy
except Exception:
    # Minimal fallbacks if libs missing
    def load_beacons(bdir):
        recs=[]
        if not os.path.exists(bdir): return recs
        for fn in os.listdir(bdir):
            p=os.path.join(bdir,fn)
            try:
                if fn.endswith('.jsonl'):
                    with open(p,'r',encoding='utf-8') as f:
                        for line in f:
                            line=line.strip()
                            if not line: continue
                            recs.append(json.loads(line))
                elif fn.endswith('.json'):
                    with open(p,'r',encoding='utf-8') as f:
                        obj=json.load(f)
                    if isinstance(obj,list): recs+=obj
                    elif isinstance(obj,dict): recs.append(obj)
            except Exception:
                pass
        return recs
    def advise_all(): return {}
    def compute_centers(recs, window=None, min_samples=1):
        # crude centers per agent band
        byA={}
        for r in recs:
            a=r.get('agent'); d=r.get('sentinel_delta')
            try: d=float(d)
            except: continue
            band=r.get('state') or ''
            byA.setdefault(a,{}).setdefault(band,[]).append(d)
        out={}
        for a,bmap in byA.items():
            out[a]={}
            for band,vals in bmap.items():
                out[a][band]=sum(vals)/len(vals)
        return out
    def compute_per_agent_entropy(recs, advice, cfg, dynamic_centers=None, window=10):
        # placeholder summary
        return {}

AGENT = "Zephyr IV"
BDIR = 'storage/shared/meta/sas/beacons'
# Label patterns for CPS_v1
RX = {
    "A2p": re.compile(r"CPS_v1:\s*A2[_ ]?baseline[_ ]?sentinel", re.I),
    "D1":  re.compile(r"CPS_v1:\s*D1[_ ]?deep[_ ]?train", re.I),
    "D2":  re.compile(r"CPS_v1:\s*D2[_ ]?deep[_ ]?train", re.I),
    "D3":  re.compile(r"CPS_v1:\s*D3[_ ]?deep[_ ]?train", re.I),
    "R2p": re.compile(r"CPS_v1:\s*R2[_ ]?recovery[_ ]?sentinel", re.I),
}
TMAP = {"A2p":385, "D1":386, "D2":387, "D3":388, "R2p":390}

def fnum(x):
    try: return float(x)
    except: return None

def norm(r):
    rr=dict(r)
    rr['_phase']=r.get('phase_label') or r.get('notes') or ''
    rr['_lt']=r.get('last_sentinel_tick') or r.get('tick')
    rr['sentinel_delta']=fnum(r.get('sentinel_delta'))
    return rr

recs=[]
for r in load_beacons(BDIR):
    if r.get('agent')!=AGENT: continue
    rr=norm(r)
    if rr['sentinel_delta'] is None: continue
    recs.append(rr)

# Select by explicit label first (newest wins), then by last_sentinel_tick fallback
def select(key):
    # label
    for r in reversed(recs):
        if isinstance(r.get('_phase'),str) and RX[key].search(r['_phase']): return r
    # tick fallback
    for r in reversed(recs):
        try:
            if int(r.get('_lt') or -1)==TMAP[key]: return r
        except: pass
    return None

sel={k:select(k) for k in ["A2p","D1","D2","D3","R2p"]}

def ratio(deep, base):
    if not deep or not base: return None
    s=fnum(base.get('sentinel_delta'))
    d=fnum(deep.get('sentinel_delta'))
    if s and s>0 and d is not None: return d/s
    return None

out={
    "present": {k:(sel[k] is not None) for k in sel},
    "deltas": {k: (None if sel[k] is None else sel[k]['sentinel_delta']) for k in sel},
    "ratios_vs_R2p": {k: (None if k=="A2p" else ratio(sel[k], sel["R2p"])) for k in sel},
    "expected_ratio": 2.5
}

centers=compute_centers(recs, window=None, min_samples=1)
advice=advise_all()
entropy=compute_per_agent_entropy(recs, advice, {}, dynamic_centers=centers, window=10)
out["centers_snapshot"]=centers.get(AGENT,{})
out["entropy_snapshot"]=entropy.get(AGENT,{})

# Aggregate deep mean ratio (D1..D3)
rs=[out["ratios_vs_R2p"].get(k) for k in ["D1","D2","D3"]]
rs=[r for r in rs if isinstance(r,(int,float))]
out["deep_mean_ratio_vs_R2p"]= (sum(rs)/len(rs) if rs else None)

print(json.dumps(out, indent=2))
